'use strict';

// Additive save migration: existing version-one stories keep their progress.
const FURNITURE=[
 {id:'bed',name:'Linen bed',w:2,h:3,price:1100,color:'#c8d7bd'},
 {id:'sofa',name:'Terracotta sofa',w:3,h:1,price:1500,color:'#c78b72'},
 {id:'desk',name:'Writing desk',w:2,h:1,price:750,color:'#c4a579'},
 {id:'chair',name:'Everyday chair',w:1,h:1,price:250,color:'#96a78a'},
 {id:'plant',name:'Coastal palm',w:1,h:1,price:150,color:'#8ba77c'},
 {id:'lamp',name:'Warm floor lamp',w:1,h:1,price:350,color:'#d5bc81'},
 {id:'shelf',name:'Oak bookcase',w:2,h:1,price:650,color:'#bca17a'},
 {id:'table',name:'Coffee table',w:2,h:1,price:450,color:'#c6a982'}
];
const RESIDENTS=[
 {id:'ada',name:'Ada',color:'#b4836a',about:'Neighbourhood gardener',route:['home','market','waterfront','home'],activities:{home:'Watering the courtyard plants',market:'Looking for fresh herbs',waterfront:'Enjoying the sea breeze'},intro:'I’m Ada. I live near Palm House. If you see a balcony full of herbs, that’s probably mine.',city:'Sunbird Market is busiest in the morning. I like the waterfront when it gets quieter.',work:'The café pays better than the market. A little studying at the library helps with either job.',home:'One plant and a warm lamp can make even a shared room feel like yours.',familiar:'There you are! The basil survived another day. How is your little place coming along?'},
 {id:'tobi',name:'Tobi',color:'#859c84',about:'Courier & shortcut enthusiast',route:['market','cafe','library','waterfront'],activities:{market:'Collecting a delivery',cafe:'Taking a tea break',library:'Dropping off some books',waterfront:'Stretching his legs'},intro:'Tobi. I deliver half the things in Old Town. Still finding new shortcuts, though.',city:'Old Town is small once you know the crossings. I stop at Mango & Co. between deliveries.',work:'Try studying before a long shift. Every skill level adds ₭100 to your pay.',home:'A desk by the window. That would be my first purchase. Somewhere to make plans.',familiar:'My favourite neighbour! Walk with me for a bit. There’s always time between deliveries.'},
 {id:'nia',name:'Nia',color:'#bea46f',about:'Painter & sunset collector',route:['waterfront','cafe','studio','library'],activities:{waterfront:'Sketching the boats',cafe:'Finding inspiration over coffee',studio:'Looking at the balconies',library:'Browsing the art shelves'},intro:'I’m Nia. I paint the bay, mostly. The light never does the same thing twice.',city:'Driftwood Walk is my favourite. Even an ordinary afternoon looks like a painting there.',work:'Earn enough to breathe, then leave a little time for something you love.',home:'Try a terracotta sofa and a plant. Warm colours make a room feel like a hug.',familiar:'I was hoping I’d run into you. I found a colour that looks just like the bay this morning.'},
 {id:'sami',name:'Sami',color:'#a0a3b8',about:'Reader & café regular',route:['library','cafe','market','home'],activities:{library:'Reading another chapter',cafe:'Waiting for a favourite brew',market:'Picking up dinner',home:'Heading back to Palm House'},intro:'Sami. I moved here for a fresh start too. The library made the city feel smaller.',city:'I like places where you can sit without rushing. The Reading Room is good for that.',work:'Food and sleep first. I learned the hard way that enthusiasm won’t get you through an empty stomach.',home:'A bookcase is my idea of luxury. And a chair that’s actually yours.',familiar:'Good to see you again. I saved you a recommendation from the library.'}
];
let roomSelection=null, roomRotation=0, activeConversation=null;
function roomSize(){return state.home==='studio'?{cols:8,rows:6}:{cols:6,rows:5};}
function furnitureSpec(id){return FURNITURE.find(f=>f.id===id);}
function furnitureSize(item){const f=furnitureSpec(item.type);return item.rot%2?{w:f.h,h:f.w}:{w:f.w,h:f.h};}
function resetLife(){state.furniture=[{uid:'starter-bed',type:'bed',x:0,y:0,rot:0}];state.roomStyle='sand';state.relationships={};roomSelection=null;activeConversation=null;window.resetResidents?.();}
function migrateLife(){
 if(!Array.isArray(state.furniture))state.furniture=[{uid:'starter-bed',type:'bed',x:0,y:0,rot:0}];
 const used=new Set();state.furniture=state.furniture.filter(i=>i&&typeof i.uid==='string'&&/^[a-z0-9-]+$/.test(i.uid)&&furnitureSpec(i.type)&&!used.has(i.uid)&&used.add(i.uid)).slice(0,60).map(i=>({...i,rot:i.rot===1?1:0,x:Number.isInteger(i.x)?i.x:null,y:Number.isInteger(i.y)?i.y:null}));
 for(const item of state.furniture){if(item.x===null||item.y===null||!canPlaceFurniture(item.uid,item.x,item.y,item.rot)){item.x=null;item.y=null;}}
 if(!['sand','sage','sea'].includes(state.roomStyle))state.roomStyle='sand';
 const saved=state.relationships;state.relationships={};for(const npc of RESIDENTS){const r=saved?.[npc.id];if(r&&typeof r==='object')state.relationships[npc.id]={met:!!r.met,bond:Math.max(0,Math.min(100,Number(r.bond)||0)),chats:Math.max(0,Number(r.chats)||0),lastRewardAt:Number.isFinite(r.lastRewardAt)?r.lastRewardAt:-1000};}
 save();
}
function canPlaceFurniture(uid,x,y,rot){const item=state.furniture.find(i=>i.uid===uid);if(!item||!Number.isInteger(x)||!Number.isInteger(y)||![0,1].includes(rot))return false;const size=furnitureSize({...item,rot}),room=roomSize();if(x<0||y<0||x+size.w>room.cols||y+size.h>room.rows)return false;
 // Keep the front door free and prevent furniture from overlapping.
 if(x+size.w===room.cols&&y+size.h===room.rows)return false;
 return !state.furniture.some(other=>{if(other.uid===uid||other.x===null||other.y===null)return false;const s=furnitureSize(other);return x<other.x+s.w&&x+size.w>other.x&&y<other.y+s.h&&y+size.h>other.y;});}
function buyFurniture(type){const spec=furnitureSpec(type);if(!spec)return {ok:false,message:'Choose an item from the shop.'};if(state.furniture.length>=60)return {ok:false,message:'Your storage is full. Rearrange what you already own.'};if(state.money<spec.price)return {ok:false,message:`You need ${cash(spec.price-state.money)} more for this ${spec.name.toLowerCase()}.`};const uid='f-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);state.money-=spec.price;state.furniture.push({uid,type,x:null,y:null,rot:0});log(`Bought a ${spec.name.toLowerCase()} for ${cash(spec.price)}.`);save();render();return {ok:true,uid,message:'Bought! Choose a free square in your room to place it.'};}
function placeFurniture(uid,x,y,rot){if(!canPlaceFurniture(uid,x,y,rot))return {ok:false,message:'That spot won’t fit. Keep the doorway clear and leave space around other furniture.'};Object.assign(state.furniture.find(i=>i.uid===uid),{x,y,rot});save();return {ok:true,message:'A little more like home. Your layout is saved.'};}
function storeFurniture(uid){const item=state.furniture.find(i=>i.uid===uid);if(!item)return false;item.x=null;item.y=null;save();return true;}
function furnitureArt(type,rot=0){const art={
 bed:'<rect x="12" y="4" width="76" height="92" rx="8" fill="#a78d6d"/><rect x="17" y="10" width="66" height="81" rx="5" fill="#f2ebd9"/><rect x="21" y="14" width="27" height="19" rx="5" fill="#fffaf0"/><rect x="52" y="14" width="27" height="19" rx="5" fill="#fffaf0"/><rect x="17" y="40" width="66" height="51" rx="3" fill="#afc0a0"/><path d="M20 48H80M20 80H80" stroke="#d2dfbc" stroke-width="3"/>',
 sofa:'<rect x="4" y="15" width="92" height="73" rx="14" fill="#a86c58"/><rect x="15" y="20" width="70" height="18" rx="7" fill="#d69f85"/><rect x="16" y="43" width="31" height="34" rx="7" fill="#d7a087"/><rect x="52" y="43" width="31" height="34" rx="7" fill="#d7a087"/><path d="M10 35V76M90 35V76" stroke="#bb8069" stroke-width="9" stroke-linecap="round"/>',
 desk:'<rect x="5" y="10" width="90" height="78" rx="5" fill="#947853"/><rect x="5" y="10" width="90" height="68" rx="5" fill="#c8ad82"/><rect x="47" y="21" width="34" height="36" rx="3" fill="#ede7d4"/><path d="M53 29H73M53 37H76M53 45H68" stroke="#b2b8a0" stroke-width="2"/><circle cx="25" cy="32" r="9" fill="#82947d"/>',
 chair:'<rect x="20" y="6" width="60" height="29" rx="9" fill="#6d8268"/><rect x="17" y="34" width="66" height="53" rx="12" fill="#a2b38e"/><path d="M23 85V94M77 85V94" stroke="#687961" stroke-width="5"/>',
 plant:'<circle cx="50" cy="57" r="29" fill="#c18b66"/><circle cx="50" cy="54" r="23" fill="#796e4b"/><path d="M49 59C5 57 8 10 49 46C30 5 70 2 55 47C92 6 99 56 58 57C99 62 78 96 54 66C36 99 9 76 49 59" fill="#78996b"/><path d="M50 61L31 35M52 59L72 38M52 61V25" stroke="#adc092" stroke-width="3"/>',
 lamp:'<circle cx="50" cy="55" r="29" fill="#d5cbb0"/><circle cx="50" cy="48" r="27" fill="#c6ad72"/><circle cx="50" cy="45" r="22" fill="#f0dfb0"/><circle cx="50" cy="45" r="8" fill="#fff5cc"/>',
 shelf:'<rect x="5" y="11" width="90" height="77" rx="4" fill="#8f7553"/><rect x="11" y="17" width="78" height="65" fill="#bd9e71"/><path d="M12 49H88" stroke="#876c4e" stroke-width="5"/><path d="M20 23V43M33 21V43M46 25V43M63 22V43M77 24V43M23 57V76M39 56V76M54 61V76M70 55V76" stroke="#d4d8bd" stroke-width="8"/><path d="M33 21V43M54 61V76" stroke="#b87f64" stroke-width="8"/>',
 table:'<rect x="8" y="17" width="84" height="70" rx="26" fill="#9e805b"/><rect x="8" y="10" width="84" height="67" rx="26" fill="#d1b48b"/><rect x="29" y="24" width="25" height="31" rx="3" fill="#e8e2c8"/><circle cx="67" cy="49" r="10" fill="#eee9d5"/><circle cx="67" cy="49" r="6" fill="#9d7d57"/>'
 };return `<svg viewBox="0 0 100 100" preserveAspectRatio="none" class="furniture-art" aria-hidden="true"><g transform="rotate(${rot?90:0} 50 50)">${art[type]||''}</g></svg>`;}
async function openApartment(){window.closeActivityScene?.();if(travelling)return toast('Finish your walk first.');const home=state.home==='studio'?'studio':'home';if(state.location!==home){selected=home;await travel(home);}roomSelection=null;roomRotation=0;openDialog('MY APARTMENT','');$('#dialog').classList.add('room-mode');renderRoom();}
function roomMessage(message){$('#roomMessage').textContent=message;}
function renderRoom(){const {cols,rows}=roomSize(),selectedItem=state.furniture.find(i=>i.uid===roomSelection);$('#dialogContent').innerHTML=`<div class="room-heading"><div><h2>${state.home==='studio'?'Your Olive Court studio.':'Your corner of Palm House.'}</h2><p>Buy a piece, pick a square, make it yours. Everything you own comes with you when you move.</p></div><b class="room-budget">${cash(state.money)}<small>available to spend</small></b></div><div class="room-workspace"><section class="room-scene"><div class="room-window"><span></span><span></span></div><div id="roomFloor" class="room-floor ${state.roomStyle}" style="--cols:${cols};--rows:${rows}" aria-label="Your room layout"></div><div class="room-palette"><span>ROOM COLOUR</span>${['sand','sage','sea'].map(s=>`<button data-palette="${s}" class="swatch ${s} ${state.roomStyle===s?'chosen':''}" aria-label="${s} room colour" aria-pressed="${state.roomStyle===s}"></button>`).join('')}<span class="room-door-label">↗ KEEP THE FRONT DOOR CLEAR</span></div><p id="roomMessage" class="room-message" role="status">${selectedItem?'Choose a free square to place your '+furnitureSpec(selectedItem.type).name.toLowerCase()+'.':'Select a piece in your room to move it, or buy something below.'}</p><div class="furniture-controls">${selectedItem?`<strong>${furnitureSpec(selectedItem.type).name}</strong><button id="rotateFurniture">Rotate ↻</button><button id="storeFurniture">Put in storage</button><button id="deselectFurniture">Done</button>`:'<span>Tip: furniture can be moved and stored as often as you like.</span>'}</div><h3 class="room-subheading">Your storage <span>${state.furniture.filter(i=>i.x===null).length} pieces</span></h3><div id="roomInventory" class="room-inventory">${state.furniture.filter(i=>i.x===null).map(i=>`<button data-inventory="${i.uid}" class="inventory-item ${roomSelection===i.uid?'chosen':''}">${furnitureArt(i.type)}<span>${furnitureSpec(i.type).name}</span></button>`).join('')||'<p>Nothing tucked away. Put a piece in storage to place it later.</p>'}</div></section><aside class="furniture-shop"><div class="section-label">THE LITTLE HOME STORE <span>⌂</span></div><p>Some comfort. Some character. Something that feels like you.</p>${FURNITURE.map(f=>`<div class="shop-item">${furnitureArt(f.id)}<div><b>${f.name}</b><small>${f.w} × ${f.h} squares · ${cash(f.price)}</small></div><button data-buy="${f.id}" aria-label="Buy ${f.name} for ${cash(f.price)}" ${state.money<f.price||state.furniture.length>=60?'disabled':''}>Buy</button></div>`).join('')}</aside></div>`;
 const floor=$('#roomFloor');for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const b=document.createElement('button');b.className='floor-tile'+(x===cols-1&&y===rows-1?' doorway':'');b.type='button';b.setAttribute('aria-label',x===cols-1&&y===rows-1?'Front door — keep clear':`Place selected furniture at column ${x+1}, row ${y+1}`);if(x===cols-1&&y===rows-1)b.textContent='↗';b.onclick=()=>{if(!roomSelection)return roomMessage('Select a piece of furniture first.');const result=placeFurniture(roomSelection,x,y,roomRotation);if(result.ok)renderRoom();roomMessage(result.message);};floor.append(b);}
 for(const item of state.furniture.filter(i=>i.x!==null)){const f=furnitureSpec(item.type),size=furnitureSize(item),b=document.createElement('button');b.className='placed-furniture'+(item.uid===roomSelection?' chosen':'');b.type='button';b.setAttribute('aria-label',`Select ${f.name}, column ${item.x+1}, row ${item.y+1}`);b.title=f.name;b.style.left=(item.x/cols*100)+'%';b.style.top=(item.y/rows*100)+'%';b.style.width=(size.w/cols*100)+'%';b.style.height=(size.h/rows*100)+'%';b.innerHTML=`<span class="furniture-picture">${furnitureArt(item.type,item.rot)}</span><span class="furniture-name">${f.name}</span>`;b.onclick=()=>{roomSelection=item.uid;roomRotation=item.rot;renderRoom();};floor.append(b);}
 $('#dialogContent').querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const result=buyFurniture(b.dataset.buy);if(result.ok){roomSelection=result.uid;roomRotation=0;renderRoom();}roomMessage(result.message);});
 $('#dialogContent').querySelectorAll('[data-inventory]').forEach(b=>b.onclick=()=>{roomSelection=b.dataset.inventory;roomRotation=state.furniture.find(i=>i.uid===roomSelection).rot;renderRoom();});
 $('#dialogContent').querySelectorAll('[data-palette]').forEach(b=>b.onclick=()=>{state.roomStyle=b.dataset.palette;save();renderRoom();});
 if(selectedItem){$('#rotateFurniture').onclick=()=>{const rot=roomRotation?0:1;if(selectedItem.x===null){selectedItem.rot=rot;roomRotation=rot;save();renderRoom();return;}const result=placeFurniture(selectedItem.uid,selectedItem.x,selectedItem.y,rot);if(result.ok){roomRotation=rot;renderRoom();}roomMessage(result.ok?'Rotated and saved.':result.message+' Try putting it in storage first.');};$('#storeFurniture').onclick=()=>{storeFurniture(selectedItem.uid);renderRoom();roomMessage('In storage. Choose a square whenever you’re ready.');};$('#deselectFurniture').onclick=()=>{roomSelection=null;renderRoom();};}
}
function relationship(id){if(!state.relationships[id])state.relationships[id]={met:false,bond:0,chats:0,lastRewardAt:-1000};return state.relationships[id];}
function friendshipLabel(id){const r=relationship(id);return !r.met?'Not met yet':r.bond>=60?'Good friend':r.bond>=25?'Friend':'Familiar face';}
function residentReply(id,topic){const npc=RESIDENTS.find(n=>n.id===id);if(!npc||!['hello','city','work','home'].includes(topic))return null;const r=relationship(id),first=!r.met,now=(state.day-1)*1440+state.minutes;let text=topic==='hello'?(r.bond>=25?npc.familiar:first?npc.intro:`Good to see you again. ${npc.city}`):npc[topic];if(topic==='hello'&&state.hunger<25)text+=' You look like you could use a meal. Don’t forget the free bread and tea at home.';if(topic==='home'&&state.home==='studio')text+=' And congratulations on your studio!';
 if(first){r.met=true;state.friends++;log(`Met ${npc.name}, ${npc.about.toLowerCase()}.`);}let rewarded=now-r.lastRewardAt>=60;if(rewarded){r.bond=Math.min(100,r.bond+10);r.lastRewardAt=now;state.mood=clamp(state.mood+8);}r.chats++;advance(10,-1,-1,0);save();render();window.reactResident?.(id,topic==='hello'?'Hello!':topic==='home'?'Make it yours.':'Good to see you.');return {text,rewarded,first};}
function renderConversation(id,result){const npc=RESIDENTS.find(n=>n.id===id),r=relationship(id);openDialog('PEOPLE OF KORA BAY',`<div class="conversation-person"><span class="resident-portrait" style="--person-colour:${npc.color}">${npc.name[0]}</span><div><h2>${npc.name}</h2><p>${npc.about}</p></div></div><div class="friendship"><span>${friendshipLabel(id)}</span><span>${r.bond}/100</span><div><i style="width:${r.bond}%"></i></div></div><p class="speech" id="residentSpeech"></p><p class="conversation-feedback">${result?.rewarded?'A good conversation. +8 mood · friendship grew.':result?'They remember you. Chat again in an hour of game time to grow your friendship.':'What would you like to say? Conversations take 10 game minutes.'}</p><div class="conversation-topics">${[['hello','Say hello'],['city','Ask about the city'],['work','Talk about work'],['home','Talk about your home']].map(([topic,text])=>`<button class="action ${topic==='hello'?'':'secondary'}" data-topic="${topic}">${text}<span>↗</span></button>`).join('')}</div>`);activeConversation=id;$('#residentSpeech').textContent=result?.text||(r.met?npc.familiar:`${npc.name} turns toward you with a smile.`);$('#dialogContent').querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>renderConversation(id,residentReply(id,b.dataset.topic)));}
async function meetResident(id){const npc=RESIDENTS.find(n=>n.id===id);if(!npc||travelling)return;travelling=true;activeConversation=id;renderLocation();try{if(window.approachResident)await window.approachResident(id);advance(5,-1,-1,0);renderConversation(id,null);window.reactResident?.(id,relationship(id).met?'Welcome back!':'Hello, neighbour!');}finally{travelling=false;renderLocation();}}
function renderResidents(){const list=$('#residents');if(!list)return;list.innerHTML=RESIDENTS.map(n=>`<button class="resident-card" data-resident="${n.id}"><span class="resident-portrait" style="--person-colour:${n.color}">${n.name[0]}</span><span><b>${n.name}<small>${friendshipLabel(n.id)}</small></b><small data-resident-status="${n.id}">${window.residentStatus?.(n.id)||n.about}</small></span><span>↗</span></button>`).join('');list.querySelectorAll('[data-resident]').forEach(b=>b.onclick=()=>meetResident(b.dataset.resident));}
function meetNeighbour(){const id=window.closestResident?.()||RESIDENTS[state.day%RESIDENTS.length].id;return meetResident(id);}
Object.assign(window,{openApartment,renderResidents,resetLife,meetResident,meetNeighbour});
$('#apartmentBtn').onclick=openApartment;
$('#dialog').addEventListener('close',()=>{activeConversation=null;});
migrateLife();renderResidents();
